  w=W(sock,rest)
  expr=r'''(()=>{const t=[...document.querySelectorAll("[data-turn-key]")];const a=t.slice(-4).map(e=>({role:e.getAttribute("data-message-author-role")||e.querySelector("[data-message-author-role]")?.getAttribute("data-message-author-role")||"",text:(e.innerText||e.textContent||"").replace(/\s+/g," ").trim().slice(-1600)}));const b=[...document.querySelectorAll("button,[role=button]")];const high=b.some(e=>/^(Высокий|High)$/iu.test((e.innerText||"").trim()));const stop=b.some(e=>/stop-button/i.test(e.getAttribute("data-testid")||"")||/остановить|stop generating|stop response/iu.test((e.innerText||"")+" "+(e.getAttribute("aria-label")||"")));const alerts=[...document.querySelectorAll("[role=alert]")].filter(e=>!e.closest("[data-turn-key]")).map(e=>(e.innerText||"").replace(/\s+/g," ").trim().slice(0,250)).filter(Boolean).slice(-4);return{url:location.href,title:document.title,ready:document.readyState,turnCount:t.length,lastTurns:a,high,stop,alerts,composerPresent:!!document.querySelector("#prompt-textarea")}})()'''
  command={"id":1,"method":"Runtime.evaluate","params":{"expression":expr,"returnByValue":True,"awaitPromise":False}}
  raw=json.dumps(command,separators=(",",":"),ensure_ascii=False).encode("utf-8")
  n=len(raw);header=b"\x81"
  if n<126:header+=bytes([0x80|n])
  elif n<65536:header+=b"\xfe"+struct.pack("!H",n)
  else:header+=b"\xff"+struct.pack("!Q",n)
  mask=os.urandom(4);wire=bytes(b ^ mask[i%4] for i,b in enumerate(raw))
  sock.sendall(header+mask+wire)
  for k in range(8):
   b1,b2=w.read(2);length=b2 & 0x7f
