   elif length==127:length=struct.unpack("!Q",w.read(8))[0]
   if b2 & 0x80:
    m=w.read(4)
   else:m=None
   if length>1000000:return {"error":"frame_too_large"}
   msg=w.read(length)
   if m:msg=bytes(b^m[i%4] for i,b in enumerate(msg))
   if (b1&0x0f)!=1:continue
   reply=json.loads(msg)
   if reply.get("id")!=1:continue
   if reply.get("error"):return {"error":"cdp_"+str(reply["error"])[:140]}
   rr=reply.get("result") or {}
   if rr.get("exceptionDetails"):return {"error":"cdp_exception_"+str(rr["exceptionDetails"].get("text"))}
   return rr.get("result",{}).get("value",{"error":"no_value"})
  return {"error":"no_matching_reply"}
 finally:sock.close()
def scan(c):
 pid=re.search(r"/c/([a-f0-9-]{20,})",c.get("url",""),re.I)
